package telegram

import "github.com/go-telegram/bot/models"

// Update is an alias for the Telegram bot library's Update type.
// It represents an incoming update from the Telegram Bot API.
type Update = models.Update

// MethodExtraData holds the routing metadata of one operation for Bot.BindRoute.
// Code generated by protoc-gen-route creates one value per operation.
type MethodExtraData struct {
	Command       string // Command to bind with Bot.BindCommand; empty means no command route
	CallbackQuery string // Callback route to bind with Bot.BindCallback; empty means no callback route
}

// NewMethodExtraData creates a new MethodExtraData instance from a raw string map.
// It reads the "command" and "callback_query" keys; missing keys leave the
// corresponding field empty. raw may be nil.
func NewMethodExtraData(raw map[string]string) *MethodExtraData {
	return &MethodExtraData{
		Command:       raw["command"],
		CallbackQuery: raw["callback_query"],
	}
}
